// Third-party kanji data (CC BY-SA). See LICENSE-DATA.md. Generated by tools/importKanji.py.
// Both files are large, so they are loaded on demand (separate chunks), never in the main bundle.

/** A named component of a kanji from KanjiVG's group hierarchy (`k` = its own sub-components). */
export type Part = { c: string; k: Part[] };

export type GraphKanji = {
  /** English meanings (KANJIDIC2). Vietnamese meanings live in lib/japanese/kanji.ts only. */
  en?: string;
  on?: string[];
  kun?: string[];
  strokes?: number;
  grade?: number;
  /** Pre-2010 four-level JLPT scale (4 easiest). */
  jlptOld?: number;
  /** Newspaper frequency rank (1 = most common). */
  freq?: number;
  radN?: number;
  radC?: string | null;
  parts: Part[];
  /** KRADFILE parts (flat); a single entry equal to the kanji itself means no further parts. */
  krad?: string[] | null;
};

export type KanjiGraphData = {
  meta: Record<string, unknown>;
  kanji: Record<string, GraphKanji>;
  /** Kanji that contain the key as a direct component, most frequent first. */
  usedIn: Record<string, string[]>;
};

export const loadKanjiGraph = () => import("./graph.json").then((m) => m.default as unknown as KanjiGraphData);
const buckets = import.meta.glob("./strokes/*.json", { import: "default" }) as Record<string, () => Promise<Record<string, string[]>>>;

/** SVG path `d` strings in drawing order (KanjiVG, 109x109 viewBox), or null when there is none. One small file per code-point bucket. */
export async function loadStrokes(char: string): Promise<string[] | null> {
  const load = buckets[`./strokes/${(char.codePointAt(0)! >> 8).toString(16)}.json`];
  return load ? ((await load())[char] ?? null) : null;
}

/** All stroke buckets merged (kanji -> SVG paths), for the handwriting matcher. About 2 MB, loaded only when that mode is first used. */
export async function loadAllStrokes(): Promise<Record<string, string[]>> {
  const parts = await Promise.all(Object.values(buckets).map((load) => load()));
  return Object.assign({}, ...parts);
}
